// Claude 自動レビュー本文の整形・判定ロジック（純関数）。
// workflow の inline JS から切り出し、tests/unit/claude-review-format.test.ts で
// 検証する。伏字化は公開 PR コメントへのシークレット漏洩を防ぐ最後の防波堤の
// ため、変更時は必ずテストを更新すること。

// 既知のトークン形式。GitHub のシークレットマスキングはログにのみ効き、
// API のコメント本文には適用されないため、投稿前に伏字化する。
// 末尾に否定先読みを置かない: 貪欲マッチと組み合わせると
// `ghp_..._` や `github_pat_...-` のような実トークンが素通りする
// fail-open になるため。過剰伏字化は安全側。
const SECRET_PATTERN_SOURCE =
  '\\b(sk-ant-[A-Za-z0-9_-]{10,}|gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})'

// issue comment 上限 65536 文字に対して余裕を持つしきい値。
// プロンプトで 6000 字以内を指示しているが出力は強制されないため、
// 実運用に近い値で安全網として機能させる。
export const MAX_BODY_LENGTH = 20000

export function redactSecrets(text) {
  // 呼び出しごとに new RegExp で生成するのは lastIndex の持ち越し事故を防ぐため
  // （stateful な .test()/.exec() とモジュール定数の正規表現を共有しない）。
  return text.replace(new RegExp(SECRET_PATTERN_SOURCE, 'g'), '[REDACTED]')
}

// 上限超過時は行単位で切り詰める（サロゲートペアを分割しないようコードポイント
// 単位で数える）。未閉じのコードフェンスは常に判定して補完し、切り詰め時は
// フェンスを閉じてから省略注記を足す（注記がコードブロックに飲み込まれるのを防ぐ）。
// 返り値は本文部分を MAX_BODY_LENGTH 以内に保ち、閉じフェンスと注記を加算する
// （最大 +16 コードポイント。issue comment 上限 65536 に対して十分な余裕がある）。
export function truncateAndCloseFences(text) {
  const chars = Array.from(text)
  let result = text
  const needsTruncation = chars.length > MAX_BODY_LENGTH
  if (needsTruncation) {
    const truncated = chars.slice(0, MAX_BODY_LENGTH).join('')
    const lastNewline = truncated.lastIndexOf('\n')
    result = lastNewline > 0 ? truncated.slice(0, lastNewline) : truncated
  }
  // 行頭の ``` のみ数える簡易ヒューリスティック（4連バッククォートの入れ子や
  // フェンス内の例示は誤判定し得る）。フッター/注記を守る目的では十分。
  const fenceCount = result
    .split('\n')
    .filter((line) => line.trim().startsWith('```')).length
  if (fenceCount % 2 === 1) {
    result += '\n```'
  }
  if (needsTruncation) {
    result += '\n\n（長すぎるため省略）'
  }
  return result
}

// レビュー本文から投稿コメント本文を組み立てる。伏字化 → 切り詰め → 組み立ての
// 順序を1箇所に固定する（順序が逆転すると伏字化が効かなくなるため、テストで
// 回帰を守る）。
export function buildReviewCommentBody({ marker, shortSha, commitUrl, reviewText }) {
  const safe = truncateAndCloseFences(redactSecrets(reviewText))
  return (
    `${marker}\n## Claude Auto Review\n\n` +
    `Reviewed commit: [\`${shortSha}\`](${commitUrl})\n\n` +
    `${safe}\n\n` +
    `*Generated by Claude Code (opus)*`
  )
}

// このワークフローが投稿した既存レビューコメントかを判定する。
// マーカーは誰でも知り得るため、投稿者を github-actions[bot] に限定して
// 第三者（他のボット含む）コメントの誤上書きを防ぐ。
export function isOwnReviewComment(comment, marker) {
  return (
    comment?.user?.login === 'github-actions[bot]' &&
    comment.body?.split('\n', 1)[0].trim() === marker
  )
}
